    {
        var d = data;
        var h = node.Index;
        var o = InitializerOffsets[d[h] & KindMask];
        if ((uint)o < SideOffset)
        {
            d[h + o] = value.Index;
            return;
        }
        if (o != SideOffset)
        {
            ThrowNoField(d[h], nameof(Initializer));
        }
        SetSideInt(h, 11, value.Index);
    }

