    {
        var d = data;
        var h = node.Index;
        var o = TypeParametersOffsets[d[h] & KindMask];
        if ((uint)o < SideOffset)
        {
            d[h + o] = value.Index;
            return;
        }
        if (o != SideOffset)
        {
            ThrowNoField(d[h], nameof(TypeParameters));
        }
        SetSideInt(h, 29, value.Index);
    }

